package com.aabhix.camera;

import android.app.*;import android.content.*;import android.graphics.*;import android.os.Build;import android.text.*;import android.view.*;import android.widget.*;import java.util.function.Consumer;

/** Full-page editor with a live sample and explicit, validated saving. */
public final class WatermarkEditor extends Dialog {
    private final Activity activity;private final android.content.SharedPreferences prefs;private final Consumer<WatermarkSettings> saved;private final Bitmap scene;
    private final boolean videoPreview;private boolean restoringSwitch;private EditText text;private Switch photo,video;private SeekBar size,opacity;private Spinner position;private Sample sample;
    public WatermarkEditor(Activity activity,Bitmap scene,boolean videoPreview,Consumer<WatermarkSettings> saved){super(activity,android.R.style.Theme_Material_NoActionBar);this.activity=activity;this.scene=scene;this.videoPreview=videoPreview;this.saved=saved;prefs=activity.getSharedPreferences("settings",0);}
    private int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
    private TextView label(String value,int sp){TextView view=new TextView(activity);view.setText(value);view.setTextColor(Color.WHITE);view.setTextSize(sp);view.setPadding(dp(8),dp(8),dp(8),dp(8));return view;}
    private WatermarkSettings draft(){return new WatermarkSettings(photo.isChecked(),video.isChecked(),text.getText().toString().trim(),1+size.getProgress()/10f,opacity.getProgress()/100f,position.getSelectedItemPosition());}
    @Override public void show(){WatermarkSettings initial=WatermarkSettings.load(prefs);LinearLayout root=new LinearLayout(activity);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.BLACK);TextView back=label("‹   Watermark",24);back.setContentDescription("Close watermark settings");back.setOnClickListener(v->dismiss());root.addView(back);
        ScrollView scroll=new ScrollView(activity);LinearLayout body=new LinearLayout(activity);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(16),0,dp(16),dp(16));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        sample=new Sample();sample.setContentDescription("Watermark live preview");body.addView(sample,new LinearLayout.LayoutParams(-1,dp(220)));body.addView(label((videoPreview?"Video":"Photo")+" sample preview. Switches apply immediately. Save text and layout changes below.",13));
        photo=new Switch(activity);photo.setText("Photos");photo.setTextColor(Color.WHITE);photo.setChecked(initial.photo);body.addView(photo,new LinearLayout.LayoutParams(-1,dp(56)));video=new Switch(activity);video.setText("Videos");video.setTextColor(Color.WHITE);video.setChecked(initial.video);body.addView(video,new LinearLayout.LayoutParams(-1,dp(56)));
        text=new EditText(activity);text.setTextColor(Color.WHITE);text.setHintTextColor(Color.GRAY);text.setHint("Custom watermark text");text.setContentDescription("Watermark text");text.setSingleLine();text.setFilters(new InputFilter[]{new InputFilter.LengthFilter(80)});text.setText(initial.text);body.addView(text);
        body.addView(label("Position",16));position=new Spinner(activity);position.setAdapter(new ArrayAdapter<>(activity,android.R.layout.simple_spinner_dropdown_item,new String[]{"Bottom right","Bottom left","Top right","Top left"}));position.setSelection(initial.position);body.addView(position,new LinearLayout.LayoutParams(-1,dp(52)));
        body.addView(label("Size · 1–10% of image width",16));size=new SeekBar(activity);size.setContentDescription("Watermark size");size.setMax(90);size.setProgress(Math.round(initial.size*10)-10);body.addView(size,new LinearLayout.LayoutParams(-1,dp(48)));body.addView(label("Opacity",16));opacity=new SeekBar(activity);opacity.setContentDescription("Watermark opacity");opacity.setMax(100);opacity.setProgress(Math.round(initial.opacity*100));body.addView(opacity,new LinearLayout.LayoutParams(-1,dp(48)));
        body.addView(label("Original photos remain unmarked when Preserve original is enabled. Model/date/location/logo templates are not available in this editor.",13));Button save=new Button(activity);save.setText("Save watermark");save.setContentDescription("Save watermark");save.setOnClickListener(v->{WatermarkSettings mark=draft();if((mark.photo||mark.video)&&mark.text.isEmpty()){text.setError("Enter text or turn both switches off");text.requestFocus();return;}if((mark.photo||mark.video)&&mark.opacity==0){Toast.makeText(activity,"Choose opacity above zero or turn watermark off",Toast.LENGTH_SHORT).show();return;}prefs.edit().putBoolean("watermarkPhoto",mark.photo).putBoolean("watermarkVideo",mark.video).putString("watermarkText",mark.text).putFloat("watermarkSize",mark.size).putFloat("watermarkOpacity",mark.opacity).putInt("watermarkPosition",mark.position).apply();saved.accept(mark);dismiss();});root.addView(save,new LinearLayout.LayoutParams(-1,dp(56)));
        photo.setOnCheckedChangeListener((button,on)->applySwitches());video.setOnCheckedChangeListener((button,on)->applySwitches());text.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){sample.invalidate();}public void afterTextChanged(Editable e){}});SeekBar.OnSeekBarChangeListener listener=new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean user){sample.invalidate();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}};size.setOnSeekBarChangeListener(listener);opacity.setOnSeekBarChangeListener(listener);position.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int n,long id){sample.invalidate();}public void onNothingSelected(AdapterView<?> p){}});
        root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){Insets i=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(i.left,i.top,i.right,i.bottom);}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});setContentView(root);super.show();getWindow().setLayout(-1,-1);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);
    }
    private void applySwitches(){if(restoringSwitch)return;WatermarkSettings stored=WatermarkSettings.load(prefs);if((photo.isChecked()&&!stored.photo||video.isChecked()&&!stored.video)&&(stored.text.trim().isEmpty()||stored.opacity==0)){restoringSwitch=true;photo.setChecked(stored.photo);video.setChecked(stored.video);restoringSwitch=false;Toast.makeText(activity,"Save text and visible opacity before enabling",Toast.LENGTH_SHORT).show();sample.invalidate();return;}prefs.edit().putBoolean("watermarkPhoto",photo.isChecked()).putBoolean("watermarkVideo",video.isChecked()).apply();saved.accept(WatermarkSettings.load(prefs));sample.invalidate();}
    private final class Sample extends View {Sample(){super(activity);}protected void onDraw(Canvas canvas){canvas.drawColor(0xff37474f);int w=getWidth(),h=getHeight();Paint paint=new Paint();if(scene!=null&&!scene.isRecycled()){int save=canvas.save();float scale=Math.max(w/(float)scene.getWidth(),h/(float)scene.getHeight());canvas.translate((w-scene.getWidth()*scale)/2,(h-scene.getHeight()*scale)/2);canvas.scale(scale,scale);canvas.drawBitmap(scene,0,0,paint);canvas.restoreToCount(save);}else{paint.setColor(0xff547c88);canvas.drawRect(0,h*.5f,w,h,paint);}if(text!=null&&position!=null){WatermarkSettings mark=draft();if(videoPreview?mark.video:mark.photo)mark.draw(canvas,w,h);}}}
}




